issue_context.body:
I noticed that in two cases, running `msbuild /t:CompileAsn` against S.S.C.Pkcs/src in master results in differences despite the XML file having not changed.

Specifically:

```diff
diff --git a/src/libraries/System.Security.Cryptography.Pkcs/src/System/Security/Cryptography/Pkcs/Asn1/Rfc3161TimeStampReq.xml.cs b/src/libraries/System.Security.Cryptography.Pkcs/src/System/Security/Cryptography/Pkcs/Asn1/Rfc3161TimeStampReq.xml.cs
index d31c8fc0236..530d1f36ca7 100644
--- a/src/libraries/System.Security.Cryptography.Pkcs/src/System/Security/Cryptography/Pkcs/Asn1/Rfc3161TimeStampReq.xml.cs
+++ b/src/libraries/System.Security.Cryptography.Pkcs/src/System/Security/Cryptography/Pkcs/Asn1/Rfc3161TimeStampReq.xml.cs
@@ -18,7 +18,7 @@ internal partial struct Rfc3161TimeStampReq
 
         internal int Version;
         internal System.Security.Cryptography.Pkcs.Asn1.MessageImprint MessageImprint;
-        internal Oid? ReqPolicy;
+        internal Oid ReqPolicy;
         internal ReadOnlyMemory<byte>? Nonce;
         internal bool CertReq;
         internal System.Security.Cryptography.Asn1.X509ExtensionAsn[] Extensions;
diff --git a/src/libraries/System.Security.Cryptography.Pkcs/src/System/Security/Cryptography/Pkcs/Asn1/SignerInfoAsn.xml.cs b/src/libraries/System.Security.Cryptography.Pkcs/src/System/Security/Cryptography/Pkcs/Asn1/SignerInfoAsn.xml.cs
index dc2267293d8..e381bbfa7f6 100644
--- a/src/libraries/System.Security.Cryptography.Pkcs/src/System/Security/Cryptography/Pkcs/Asn1/SignerInfoAsn.xml.cs
+++ b/src/libraries/System.Security.Cryptography.Pkcs/src/System/Security/Cryptography/Pkcs/Asn1/SignerInfoAsn.xml.cs
@@ -20,7 +20,7 @@ internal partial struct SignerInfoAsn
         internal ReadOnlyMemory<byte>? SignedAttributes;
         internal System.Security.Cryptography.Asn1.AlgorithmIdentifierAsn SignatureAlgorithm;
         internal ReadOnlyMemory<byte> SignatureValue;
-        internal System.Security.Cryptography.Asn1.AttributeAsn[]? UnsignedAttributes;
+        internal System.Security.Cryptography.Asn1.AttributeAsn[] UnsignedAttributes;
 
         internal void Encode(AsnWriter writer)
         {
```

Steps to reproduce:

1. Check out master (f80a5147ef7662c3238275568c9dad7655a9684f)
2. cd `./src/libraries/System.Security.Cryptography.Pkcs/src`
3. `msbuild /t:CompileAsn`
4. `git diff` shows the diff above.

/cc @bartonjs (sorry I am noisy today)
